# ── Golden fixtures: numerical output frozen at MacroFilters 0.2.1 ───────────
#
# Generated by data-raw/golden_fixtures.R from tag v0.2.1. Any change that
# moves these numbers must be deliberate and come with a NEWS entry; in that
# case regenerate the fixtures and say so in the commit message.

golden_datasets <- function() {
  list(us = us_gdp_vintage, fr = fr_gdp, es = es_gdp)
}

golden_filters <- function() {
  list(hp = hp_filter, hamilton = hamilton_filter,
       bhp = bhp_filter, mbh = mbh_filter)
}

as_quarterly_ts <- function(dt) {
  d0 <- as.POSIXlt(dt$date[1L])
  stats::ts(dt$gdp_log, start = c(d0$year + 1900, d0$mon %/% 3 + 1),
            frequency = 4)
}

quiet <- function(expr) suppressWarnings(suppressMessages(expr))

read_golden <- function(name) {
  readRDS(test_path("fixtures", paste0(name, ".rds")))
}

# ── 1. Point estimates, default arguments ────────────────────────────────────

for (f in names(golden_filters())) {
  test_that(sprintf("%s() trend matches the 0.2.1 golden fixtures", f), {
    if (f == "mbh") skip_on_cran()
    fun <- golden_filters()[[f]]
    for (k in names(golden_datasets())) {
      dt <- golden_datasets()[[k]]
      fx <- read_golden(sprintf("%s_%s", f, k))
      expect_equal(quiet(fun(as_quarterly_ts(dt)))$trend, fx$ts,
                   tolerance = 1e-8, info = sprintf("%s / %s / ts", f, k))
      # A plain vector gives mbh_filter() frequency 1 and a tiny Huber d, the
      # degenerate fit of roadmap §1.1.1. That fit amplifies rounding: on macOS
      # arm64 the US trend moves by 3.5e-4. Compare it loosely there; 0.3.0
      # replaces this fit anyway.
      tol_num <- if (f == "mbh") 1e-4 else 1e-8
      expect_equal(quiet(fun(as.numeric(dt$gdp_log)))$trend, fx$num,
                   tolerance = tol_num, info = sprintf("%s / %s / numeric", f, k))
    }
  })
}

# ── 2. Bootstrap bands, fixed seed ───────────────────────────────────────────

for (f in names(golden_filters())) {
  test_that(sprintf("%s() bootstrap bands match the 0.2.1 golden fixtures", f), {
    if (f == "mbh") skip_on_cran()
    fx <- read_golden(sprintf("boot_%s_us", f))
    set.seed(fx$seed)
    fit <- quiet(golden_filters()[[f]](as_quarterly_ts(us_gdp_vintage),
                                       boot_iter = fx$boot_iter))
    expect_equal(fit$trend,       fx$trend, tolerance = 1e-8)
    expect_equal(fit$trend_lower, fx$lower, tolerance = 1e-8)
    expect_equal(fit$trend_upper, fx$upper, tolerance = 1e-8)
  })
}

# ── 3. External reference: mFilter ───────────────────────────────────────────

test_that("hp_filter() agrees with mFilter::hpfilter()", {
  skip_if_not_installed("mFilter")
  for (k in names(golden_datasets())) {
    y   <- as_quarterly_ts(golden_datasets()[[k]])
    ref <- mFilter::hpfilter(y, freq = 1600, type = "lambda")
    expect_equal(hp_filter(y, lambda = 1600)$trend, as.numeric(ref$trend),
                 tolerance = 1e-8, info = k)
  }
})
